<form class="surface global-filter" method="GET" action="{{ route('dashboard') }}" id="dashboardFilters">
    <div class="global-filter-grid">
        <div class="filter-field"><label for="dashboard-period">Reporting period</label><select id="dashboard-period" class="form-select" name="period" data-native-select="true"><option value="today" @selected($dashboardFilters['period']==='today')>Today</option><option value="last_7_days" @selected($dashboardFilters['period']==='last_7_days')>Last 7 days</option><option value="this_month" @selected($dashboardFilters['period']==='this_month')>This month</option><option value="last_3_months" @selected($dashboardFilters['period']==='last_3_months')>Last 3 months</option><option value="last_6_months" @selected($dashboardFilters['period']==='last_6_months')>Last 6 months</option><option value="this_year" @selected($dashboardFilters['period']==='this_year')>This year</option><option value="all_time" @selected($dashboardFilters['period']==='all_time')>All time</option><option value="custom" @selected($dashboardFilters['period']==='custom')>Custom range</option></select></div>
        <div class="filter-dates" data-custom-dates @if($dashboardFilters['period'] !== 'custom') hidden @endif><div class="filter-field"><label for="dashboard-from">From</label><input id="dashboard-from" class="form-control" type="date" name="date_from" value="{{ request('date_from', $dashboardFilters['dateFrom']?->toDateString()) }}"></div><div class="filter-field"><label for="dashboard-to">To</label><input id="dashboard-to" class="form-control" type="date" name="date_to" value="{{ request('date_to', $dashboardFilters['dateTo']?->toDateString()) }}"></div></div>
        <div class="filter-field"><label for="dashboard-gender">Gender</label><select id="dashboard-gender" class="form-select" name="gender" data-native-select="true"><option value="">All genders</option>@foreach(['Female','Male','Other'] as $gender)<option @selected(request('gender')===$gender)>{{ $gender }}</option>@endforeach</select></div>
        <div class="filter-field"><label for="dashboard-age">Age group</label><select id="dashboard-age" class="form-select" name="age" data-native-select="true"><option value="">All ages</option><option value="under_25" @selected(request('age')==='under_25')>Under 25</option><option value="25_34" @selected(request('age')==='25_34')>25–34</option><option value="35_44" @selected(request('age')==='35_44')>35–44</option><option value="45_54" @selected(request('age')==='45_54')>45–54</option><option value="55_plus" @selected(request('age')==='55_plus')>55 and over</option></select></div>
        <div class="filter-field"><label for="dashboard-type">Customer type</label><select id="dashboard-type" class="form-select" name="customer_type" data-native-select="true"><option value="">All customer types</option>@foreach($dashboardFilters['customerTypes'] as $type)<option value="{{ $type }}" @selected(request('customer_type')===$type)>{{ $type }}</option>@endforeach</select></div>
        <div class="filter-field"><label for="dashboard-product">Loan product</label><select id="dashboard-product" class="form-select" name="loan_product_id" data-native-select="true"><option value="">All loan products</option>@foreach($dashboardFilters['loanProducts'] as $product)<option value="{{ $product->id }}" @selected(request('loan_product_id')==$product->id)>{{ $product->name }}</option>@endforeach</select></div>
        <div class="filter-field"><label for="dashboard-officer">Loan officer</label><select id="dashboard-officer" class="form-select" name="officer_id" data-native-select="true"><option value="">All loan officers</option>@foreach($dashboardFilters['loanOfficers'] as $officer)<option value="{{ $officer->id }}" @selected(request('officer_id')==$officer->id)>{{ $officer->first_name }} {{ $officer->last_name }}</option>@endforeach</select></div>
        <div class="filter-actions"><button class="btn btn-primary" type="submit"><i class="mdi mdi-filter-outline me-1"></i>Apply filters</button><a class="btn btn-outline-secondary" href="{{ route('dashboard') }}">Reset</a></div>
    </div>
    <div class="filter-summary"><i class="mdi mdi-information-outline"></i><span>These filters apply consistently to Overview, Members, and Loans.</span></div>
</form>
<script>const periodSelect=document.getElementById('dashboard-period');const customDates=document.querySelector('[data-custom-dates]');periodSelect?.addEventListener('change',function(){customDates.hidden=periodSelect.value!=='custom';if(periodSelect.value!=='custom'){document.getElementById('dashboardFilters').requestSubmit();}});</script>
